UPDATE users
email = #{email,jdbcType=VARCHAR}, password_hash = #{passwordHash,jdbcType=VARCHAR}, nickname = #{nickname,jdbcType=VARCHAR}, avatar_url = #{avatarUrl,jdbcType=VARCHAR}, phone = #{phone,jdbcType=VARCHAR}, last_login_at = #{lastLoginAt,jdbcType=TIMESTAMP}, status = #{status,jdbcType=TINYINT}, updated_at = #{updatedAt,jdbcType=TIMESTAMP}, # 邀请码字段 invite_code = #{inviteCode,jdbc}
WHERE username = #{username,jdbcType=VARCHAR}
